;WITH SourceRows AS
(
    SELECT
        name,
        display_name,
        active,
        activated_at,
        deactivated_at,
        created_at
    FROM OPENJSON(@DemoTenants)
    WITH
    (
        name NVARCHAR(255) '$.name',
        display_name NVARCHAR(255) '$.display_name',
        active BIT '$.active',
        activated_at DATETIME2 '$.activated_at',
        deactivated_at DATETIME2 '$.deactivated_at',
        created_at DATETIME2 '$.created_at'
    )
)
MERGE crm.tenants AS target
USING SourceRows AS source
    ON target.name = source.name
WHEN MATCHED THEN
    UPDATE SET
        display_name = source.display_name,
        active = source.active,
        activated_at = source.activated_at,
        deactivated_at = source.deactivated_at,
        created_at = source.created_at
WHEN NOT MATCHED BY TARGET THEN
    INSERT
    (
        name,
        display_name,
        active,
        activated_at,
        deactivated_at,
        created_at
    )
    VALUES
    (
        source.name,
        source.display_name,
        source.active,
        source.activated_at,
        source.deactivated_at,
        source.created_at
    );

DELETE FROM crm.activities WHERE tenant = N'demo';
DELETE FROM crm.note_attachments WHERE tenant = N'demo';
DELETE FROM crm.deal_contacts WHERE tenant = N'demo';
DELETE FROM crm.deal_notes WHERE tenant = N'demo';
DELETE FROM crm.deals WHERE tenant = N'demo';
DELETE FROM crm.contact_tags WHERE tenant = N'demo';
DELETE FROM crm.tasks WHERE tenant = N'demo';
DELETE FROM crm.contact_notes WHERE tenant = N'demo';
DELETE FROM crm.contacts WHERE tenant = N'demo';
DELETE FROM crm.companies WHERE tenant = N'demo';
DELETE FROM crm.sales WHERE tenant = N'demo';

SET IDENTITY_INSERT crm.sales ON;

;WITH SourceRows AS
(
    SELECT
        id,
        tenant,
        user_id,
        email,
        first_name,
        last_name,
        administrator,
        disabled,
        avatar_src,
        avatar_title,
        avatar_path,
        avatar_type,
        created_at,
        updated_at,
        PasswordHash
    FROM OPENJSON(@DemoSales)
    WITH
    (
        id INT '$.id',
        tenant NVARCHAR(255) '$.tenant',
        user_id VARCHAR(50) '$.user_id',
        email NVARCHAR(320) '$.email',
        first_name NVARCHAR(100) '$.first_name',
        last_name NVARCHAR(100) '$.last_name',
        administrator BIT '$.administrator',
        disabled BIT '$.disabled',
        avatar_src NVARCHAR(500) '$.avatar_src',
        avatar_title NVARCHAR(255) '$.avatar_title',
        avatar_path NVARCHAR(500) '$.avatar_path',
        avatar_type NVARCHAR(255) '$.avatar_type',
        created_at DATETIME2 '$.created_at',
        updated_at DATETIME2 '$.updated_at',
        PasswordHash NVARCHAR(100) '$.PasswordHash'
    )
)
MERGE crm.sales AS target
USING SourceRows AS source
    ON target.id = source.id
WHEN MATCHED THEN
    UPDATE SET
        tenant = source.tenant,
        user_id = source.user_id,
        email = source.email,
        first_name = source.first_name,
        last_name = source.last_name,
        administrator = source.administrator,
        disabled = source.disabled,
        avatar_src = source.avatar_src,
        avatar_title = source.avatar_title,
        avatar_path = source.avatar_path,
        avatar_type = source.avatar_type,
        created_at = source.created_at,
        updated_at = source.updated_at,
        PasswordHash = source.PasswordHash
WHEN NOT MATCHED BY TARGET THEN
    INSERT
    (
        id,
        tenant,
        user_id,
        email,
        first_name,
        last_name,
        administrator,
        disabled,
        avatar_src,
        avatar_title,
        avatar_path,
        avatar_type,
        created_at,
        updated_at,
        PasswordHash
    )
    VALUES
    (
        source.id,
        source.tenant,
        source.user_id,
        source.email,
        source.first_name,
        source.last_name,
        source.administrator,
        source.disabled,
        source.avatar_src,
        source.avatar_title,
        source.avatar_path,
        source.avatar_type,
        source.created_at,
        source.updated_at,
        source.PasswordHash
    );

SET IDENTITY_INSERT crm.sales OFF;

SET IDENTITY_INSERT crm.companies ON;

